#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    /* The original binary expects at least two arguments after the program name:
       a mode ("escape" or "unescape") and an input string. */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    /* The original program limits the input length to 0x3ff (1023) characters.
       If the limit is exceeded it prints the usage message. */
    if (strlen(input) > 1023) {
        puts("USAGE");
        return 0;
    }

    /* Output buffer – the original code allowed up to 0x7ff (2047) bytes.
       A static buffer of that size is sufficient for the observed behaviour. */
    char out[2048];
    size_t out_len = 0;

    if (strcmp(mode, "escape") == 0) {
        for (size_t i = 0; input[i] != '\0'; ++i) {
            char c = input[i];
            if (c == '\\') {
                if (out_len + 2 >= sizeof(out)) break;
                out[out_len++] = '\\';
                out[out_len++] = '\\';
            } else if (c == '\n') {
                if (out_len + 2 >= sizeof(out)) break;
                out[out_len++] = '\\';
                out[out_len++] = 'n';
            } else if (c == '\t') {
                if (out_len + 2 >= sizeof(out)) break;
                out[out_len++] = '\\';
                out[out_len++] = 't';
            } else if (c == '"') {
                if (out_len + 2 >= sizeof(out)) break;
                out[out_len++] = '\\';
                out[out_len++] = '"';
            } else {
                if (out_len + 1 >= sizeof(out)) break;
                out[out_len++] = c;
            }
        }
        out[out_len] = '\0';
        puts(out);
    } else if (strcmp(mode, "unescape") == 0) {
        for (size_t i = 0; input[i] != '\0'; ++i) {
            char c = input[i];
            if (c == '\\') {
                char next = input[++i];
                switch (next) {
                    case 'n': out[out_len++] = '\n'; break;
                    case 't': out[out_len++] = '\t'; break;
                    case '\\': out[out_len++] = '\\'; break;
                    case '"': out[out_len++] = '"'; break;
                    default: out[out_len++] = next; break; /* undefined escape – copy as‑is */
                }
            } else {
                out[out_len++] = c;
            }
        }
        out[out_len] = '\0';
        puts(out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
